transforms.code:
try:
	key = self.session.custom.structure.configs[value]["config"]["licenseKey"]
except:
	key = "<N/A>"
return "EAM: " + (key or "<No Key>")

returnVal = {"msg": '', "total": 0, "retailTotal": 0, "licenseBase": 0, "supportBase": 0, "licenseDiscounted": 0, "supportDiscounted": 0}
total = 0

for uuid in value['gatewayUUIDs'].keys():
	if value['configs'][uuid]['type'] in ('standard', 'edge', 'cloud', 'panel'):
		if value['configs'][uuid]['type'] == 'cloud':
			returnVal['msg'] = 'Check Provider'
		elif value['configs'][uuid]['config']['trial']:
			pass
		else:
			# Build list of selected modules
			selections = {}
			eamCost = 0
			for vendor in value['configs'][uuid]['config']['modules']:
				selectedModules = []
				if len(value['configs'][uuid]['config']['modules'][vendor]) > 0:
					for m in value['configs'][uuid]['config']['modules'][vendor]:
						if "selection" in m.keys() and m["selection"] is not None:
							selectedModules.append({"name": m["name"], "selection": m["selection"]})
						else:
							selectedModules.append(m["name"])
					selections[vendor] = selectedModules
				if vendor == "IA" and value["eamUnlimited"]["selected"]:
					if len(filter(lambda module: module == "EAM", selections["IA"])) > 0:
						for module in selections["IA"]:
							if module == "EAM":
								selections["IA"].remove(module)
								break
					if value["eamUnlimited"]["UUID"] == uuid:
						selectedModules.append({"name": "EAM", "selection": "unlimited"})
						returnVal["eamCost"] = exchange.architecturebuilder.modules.getEamUnlimited()
			licenseBase = exchange.architecturebuilder.modules.getRetailTotal(selections, gwType=value['configs'][uuid]['type'])['total']
			supportBase = exchange.architecturebuilder.modules.getSupportTotal(selections, supportPlan=value['configs'][uuid]['config']['supportPlan'], gwType=value['configs'][uuid]['type'])['total']

			# Calculate total with discount and redundancy/development modifiers
			license = licenseBase
			support = supportBase
			if value['configs'][uuid]['config']['redundant']:
				license = license * 1.5
				support = support * 1.5
			if value['configs'][uuid]['config']['development']:
				license = license * 0.5
				support = support * 0.5
			retailTotal = license + support
			licenseDiscounted = (license * (1 - (value['discount'] / 100.0)))
			supportDiscounted = support * 0.9 if value['discount'] > 0 else support

			# Increment dictionary values
			returnVal['licenseBase'] += licenseBase
			returnVal['supportBase'] += supportBase
			returnVal['retailTotal'] += retailTotal
			returnVal['licenseDiscounted'] += licenseDiscounted
			returnVal['supportDiscounted'] += supportDiscounted
			returnVal['total'] += licenseDiscounted + (supportDiscounted if value["supportCosts"] else 0)
return returnVal

