# Return list of Ignition Gateway UUIDs that are children of the specified area
def areaSearch(targetUUID, entry, path, areaFound, children):
	for e in entry:
		if e['type'] == 'Container':
			if path == '':
				areaSearch(targetUUID, e['contents'], e['uuid'], areaFound or e['uuid'] == targetUUID, children)
			else:
				areaSearch(targetUUID, e['contents'], path + '@' + e['uuid'], areaFound or e['uuid'] == targetUUID, children)
		elif areaFound and e['type'] in ('standard', 'edge', 'panel', 'cloud'):
			children.append(e['uuid'])
	return children

def search(accordion, entry, path):
	if logger.isTraceEnabled():
		logger.trace("Search called with accordion = '%s', entry = '%s', path = '%s'"% (accordion, entry, path))
	for e in entry:
		if logger.isDebugEnabled():
			logger.debug("Processing entry '%s' of type '%s'"% (e, e['type']))
		if e['type'] in ('Container', 'standard', 'edge', 'panel', 'cloud'):
			if e['type'] == 'Container':
				# Add Area entry
				item = areaAccordion()
				item['body']['viewParams']['parents'] = path
				item['body']['viewParams']['uuid'] = e['uuid']
				item['body']['viewParams']['supportCosts'] = visibility["support"]
				item['body']['viewParams']['children'] = areaSearch(e['uuid'], value['structure'], '', False, [])
				accordion.append(item)

				# Recursively search for contents
				if path == '':
					search(accordion, e['contents'], e['uuid'])
				else:
					search(accordion, e['contents'], path + '@' + e['uuid'])

			if e['type'] in ('standard', 'edge', 'panel', 'cloud'):
				item = stdAccordion()
				# Get Ignition Edition
				gwType = value['configs'][e['uuid']]['type'].capitalize()
				# Set header properties
				item['header']['content']['viewPath'] = "Exchange/ArchitectureBuilder/BOM/Ignition/Header"
				item['header']['content']['viewParams'] = {
					"name": e['name'],
					"parents": path,
					"type": gwType,
					"uuid": e['uuid']
				}
				# Set body properties
				item['body']['viewPath'] = "Exchange/ArchitectureBuilder/BOM/Ignition/Body"
				item['body']['viewParams'] = {
					"type": gwType,
					"uuid": e['uuid']
				}
				item['body']['style']['borderBottomColor'] = "var(--" + gwType.lower() + ")"
				item['body']['style']['borderRightColor'] = "var(--" + gwType.lower() + ")"
				item['body']['style']['borderLeftColor'] = "var(--" + gwType.lower() + ")"
				# Append to accordion list
				accordion.append(item)

			# Build dictionary to retain visibility/expansion selections
			# 	Copy existing values when present
			if len(visibility["gateways"]) > 0 and e["uuid"] in visibility["gateways"].keys():
				item["body"]["viewParams"]["visibility"] = {}
				item["body"]["viewParams"]["visibility"]["expanded"] = visibility["gateways"][e["uuid"]]["expanded"]
				item["header"]["content"]["viewParams"]["expanded"] = visibility["gateways"][e["uuid"]]["entryExpanded"]
				item["expanded"] = visibility["gateways"][e["uuid"]]["entryExpanded"]
				gwVisibility[e["uuid"]] = {
					"entryExpanded": visibility["gateways"][e["uuid"]]["entryExpanded"],
					"expanded": visibility["gateways"][e["uuid"]]["expanded"]
					}
			else:
				item["header"]["content"]["viewParams"]["visibility"] = True
				item["expanded"] = True
				item["body"]["viewParams"]["visibility"] = {
					"expanded": {
						"gatewayConfig": True,
						"IA": True,
						"CL": True,
						"TPM": True,
						"computing": True,
						"SS": True,
						"support": True
						},
					"entryExpanded": True
					}
				gwVisibility[e["uuid"]] = {
					"expanded": {
						"gatewayConfig": True,
						"IA": True,
						"CL": True,
						"TPM": True,
						"computing": True,
						"SS": True,
						"support": True
						},
					"entryExpanded": True
					}				
			item["body"]["viewParams"]["visibility"]["display"] = {key: visibility[key] for key in ["computing", "gatewayConfig", "support"]}
			item["header"]["content"]["viewParams"]["supportCosts"] = visibility["support"]
	return accordion

