onChange.script:
for attr in ("computing", "gatewayConfig", "support"):
	if currentValue.value[attr] != previousValue.value[attr]:
		for item in self.props.items:
			item["body"]["viewParams"]["visibility"]["display"][attr] = currentValue.value[attr]
		if attr == "support":
			for item in self.props.items:
				if item["body"]["viewPath"] == "Exchange/ArchitectureBuilder/BOM/Areas/Body":
					item["body"]["viewParams"]["supportCosts"] = currentValue.value[attr]
				else:
					item["header"]["content"]["viewParams"]["supportCosts"] = currentValue.value[attr]

